def float_to_binary_embedding(float_query_embedding: dict) -> dict:
    """Utility function to convert float query embeddings to binary query embeddings."""
    if not float_query_embedding:
        return {}
    binary_vectors = (
        np.packbits(np.array(list(float_query_embedding.values())) > 0, axis=-1).astype(np.int8).tolist()
    )
    return dict(zip(float_query_embedding.keys(), binary_vectors))

