def what_language(el):
    text = el.text
    z = re.match(r"{%\s*highlight\s*(\w+)\s%}", text)
    if z:
        lang =  z.group(1)
        return lang
    if text.find("curl") > 0:
        return "bash"
    if text.find("import com.yahoo") > 0:
        return "java"
    return ""

